	/* @Override */
	public void registerOption(string optionName, OptionType type, object defaultValue,
			HelpLocation help, string description, Supplier<PropertyEditor> editorSupplier) {

		if (type == OptionType.NO_TYPE) {
			throw new IllegalArgumentException(
				"Can't register an option of type: " + OptionType.NO_TYPE);
		}

		if (type == OptionType.COLOR_TYPE) {
			warnShouldUseTheme("Color");
		}
		if (type == OptionType.FONT_TYPE) {
			warnShouldUseTheme("font");
		}
		if (type == OptionType.KEYSTROKE_TYPE) {
			type = OptionType.ACTION_TRIGGER;
			if (defaultValue is KeyStroke) {
				defaultValue = new ActionTrigger((KeyStroke) defaultValue);
			}
			if (editorSupplier != null) {
				Msg.error(this, "Custom KeyStroke property editors are no longer supported.  " +
					"Use ActionTrigger instead");
				editorSupplier = null;
			}
		}

		if (!type.isCompatible(defaultValue)) {
			throw new IllegalStateException(
				"Given default value does not match the given OptionType! OptionType = " + type +
					", defaultValue = " + defaultValue);
		}

		editorSupplier = Dummy.ifNull(editorSupplier);
		PropertyEditor editor = null;
		bool isHeadless = SystemUtilities.isInHeadlessMode();
		if (!isHeadless) {
			editor = editorSupplier.get();
		}

		if (type == OptionType.CUSTOM_TYPE) {
			if (!isHeadless && editor == null) {
				throw new IllegalStateException(
					"Can't register a custom option without a property editor");
			}
		}

		if (description == null) {
			Msg.error(this, "Registered an option without a description: " + optionName,
				ReflectionUtilities.createJavaFilteredThrowable());
		}

		lock (this) {

			Option currentOption = getExistingComptibleOption(optionName, type);
			if (currentOption != null) {
				currentOption.updateRegistration(description, help, defaultValue, editor);
				return;
			}

			Option option =
				createRegisteredOption(optionName, type, description, help, defaultValue, editor);
			valueMap.put(optionName, option);
		}
	}

	private void warnShouldUseTheme(string optionType) {
		Throwable throwable = ReflectionUtilities
				.createThrowableWithStackOlderThan(typeof(AbstractOptions), typeof(SubOptions));
		string call = throwable.getStackTrace()[0].toString();
		Msg.warn(this, "Registering a direct " + optionType + " in the options is deprecated." +
			" Use registerTheme" + optionType + "Binding() instead!\n Called from " + call + "\n");
	}

	/* @Override */
	public void registerThemeColorBinding(string optionName, string colorId, HelpLocation help,
			string description) {
		Option currentOption = getExistingComptibleOption(optionName, OptionType.COLOR_TYPE);
		if (currentOption != null && currentOption is ThemeColorOption) {
			currentOption.updateRegistration(description, help, null, null);
			return;
		}
		description += " (Theme Color: " + colorId + ")";
		Option option = new ThemeColorOption(optionName, colorId, description, help);
		valueMap.put(optionName, option);
	}

	/* @Override */
	public void registerThemeFontBinding(string optionName, string fontId, HelpLocation help,
			string description) {
		if (Gui.getFont(fontId) == null) {
			throw new IllegalArgumentException("Invalid theme font id: \"" + fontId + "\"");
		}
		Option currentOption = getExistingComptibleOption(optionName, OptionType.FONT_TYPE);
		if (currentOption != null && currentOption is ThemeFontOption) {
			currentOption.updateRegistration(description, help, null, null);
			return;
		}
		description += " (Theme Font: " + fontId + ")";
		Option option = new ThemeFontOption(optionName, fontId, description, help);
		themeToOptionMap.put(fontId, optionName);
		valueMap.put(optionName, option);
	}

	private Option getExistingComptibleOption(string optionName, OptionType type) {

		// There are several cases where an existing option may exist when registering an option
		// 1) the option was accessed before it was registered
		// 2) the option was loaded from a store (database or tool state)
		// 3) the option was registered more than once.
		//
		// The only time this is a problem is if the exiting option type is not compatible with
		// the type being registered.  If we encounter an incompatible option, we just log a
		// warning and return null so that the new option will replace it. Otherwise, we return
		// the existing option so it can be updated with the data from the registration.

		Option option = valueMap.get(optionName);
		if (option == null) {
			return null;
		}
		OptionType existingType = option.getOptionType();
		if (existingType != type) {
			Msg.error(this, "Registered option incompatible with existing option: '%s'. " +
				"Existing type '%s'; registered type '%s'.".formatted(optionName, existingType,
					type),
				new AssertException());
			return null;
		}
		return option;
	}

